{"command":"create","path":"/workspace/codebase/src-rust/main.rs","file_text":"use std::env;
use std::io;
use std::path::PathBuf;
use std::process::{Command, ExitCode};

fn main() -> ExitCode {
    if let Err(error) = run() {
        eprintln!("jscodeshift: {error}");
        return ExitCode::from(1);
    }
    ExitCode::SUCCESS
}

fn run() -> io::Result<()> {
    let package_root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let bridge = package_root.join("bridge").join("transform-host.js");
    let node = env::var_os("JSCODE_SHIFT_NODE").unwrap_or_else(|| "node".into());

    let status = Command::new(node)
        .arg(bridge)
        .args(env::args_os().skip(1))
        .current_dir(package_root)
        .status()?;

    match status.code() {
        Some(code) if code != 0 => {
            std::process::exit(code);
        }
        None => {
            // Preserve the conventional shell status for a process terminated by signal.
            std::process::exit(128);
        }
        _ => Ok(()),
    }
}
"}

